def setUp(self):
        self.init_replay_file = os.path.join(get_main_dir(), "tests", "utilcmd", "adlenumerate.json")
        self._tmpfiles = []

def tearDown(self):
        for path in self._tmpfiles:
            try:
                if os.path.isfile(path):
                    os.remove(path)
                elif os.path.isdir(path):
                    shutil.rmtree(path)
            except OSError as exc:
                logger().log_error(f"Failed to remove temporary path {path}: {exc}")

def add(app):
    @app.task(bind=True, max_retries=3, default_retry_delay=1)
    def add(self, x, y):
        time.sleep(0.05)
        return x + y
    return add

def summarize(app):
    @app.task(bind=True, max_retries=3, default_retry_delay=1)
    def summarize(self, results):
        return sum(results)
    return summarize

