def _clear_image_cache_after_module():
    """The glyph icons these toasts render populate the process-global
    ``Style._image_cache``; clear it on teardown so this module imposes no
    test-order dependency on ``widget_styles/test_image_cache``.
    """
    yield
    try:
        Style.get_instance().clear_image_cache()
    except Exception:
        pass

def restore_fonts(root):
    """Snapshot + restore the managed named fonts, the wrapper cache, and the
    pending-config registry so a test that pokes them does not leak."""
    before = {}
    for name in Fonts.names():
        try:
            before[name] = dict(font.nametofont(name, root=root).actual())
        except Exception:
            pass
    pending_before = dict(config._pending)
    try:
        yield root
    finally:
        for name, spec in before.items():
            try:
                font.nametofont(name, root=root).configure(**spec)
            except Exception:
                pass
        Fonts.reset()
        config._pending.clear()
        config._pending.update(pending_before)

def _isolate_user_options(root):
    """Reset durable overrides and rebuild touched base styles after each test."""
    yield
    style = root.style
    style.reset_style_options()
    builder = style._get_builder()
    for variant, family in (
        ("default", "entry"),
        ("default", "panedwindow"),
        ("default", "button"),
    ):
        try:
            builder.build_style(variant, family, "default")
        except Exception:
            pass

def _isolate(root):
    yield
    style = root.style
    style.reset_style_options()
    for name in ("Treeview", "Table.Treeview"):
        style._build_configure(name, font="TkDefaultFont")
    for variant in ("default", "table"):
        try:
            _rebuild(root, variant)
        except Exception:
            pass

