def _e2e_preflight():
    if os.environ.get("HATE_CRACK_HASHCAT_REAL") != "1":
        yield
        return
    hazard = _isolation_hazard()
    if hazard:
        pytest.skip(hazard)
    missing = _missing_required_binaries()
    if missing:
        pytest.skip("Missing required e2e binaries: " + "; ".join(missing))
    yield

